<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>VoltSeal Carbon Footprint Calculator</title>
<style>
  *{box-sizing:border-box}
  html,body{margin:0;padding:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Inter,Roboto,"Helvetica Neue",Arial,sans-serif;background:#F7F3EC;color:#0E3B2E}
  .app{display:flex;min-height:100vh;flex-direction:row}
  .left{width:35%;background:linear-gradient(160deg,#0E3B2E 0%,#184D3B 100%);color:#fff;padding:32px}
  .right{width:65%;padding:40px}
  .logo-wrap{padding:24px 0}
  .logo-wrap img{max-width:220px;height:auto;object-fit:contain;background:#fff;border-radius:12px;padding:10px 14px;display:block}
  h1{font-size:1.5rem;margin:16px 0 4px;font-weight:700}
  .sub{color:rgba(255,255,255,.7);font-size:.9rem;margin:0 0 24px}
  .field{margin-bottom:18px}
  .field-head{display:flex;justify-content:space-between;align-items:baseline}
  .field-head label{font-size:.9rem;font-weight:500}
  .field-head .unit{font-size:.75rem;color:rgba(255,255,255,.6)}
  .field input{margin-top:8px;width:100%;border-radius:12px;border:1px solid rgba(255,255,255,.15);background:rgba(255,255,255,.1);padding:12px 16px;color:#fff;font-size:1rem;outline:none;transition:.2s}
  .field input::placeholder{color:rgba(255,255,255,.4)}
  .field input:focus{border-color:rgba(255,255,255,.4);background:rgba(255,255,255,.15)}
  .err{color:#DC2626;font-size:13px;font-weight:500;text-align:left;margin-top:4px;min-height:18px}
  .err:empty{min-height:18px}
  .assumptions{margin-top:24px;padding:20px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.05);border-radius:16px}
  .assumptions h3{margin:0 0 10px;font-size:.8rem;letter-spacing:.08em;text-transform:uppercase;color:rgba(255,255,255,.8)}
  .assumptions ul{margin:0;padding:0;list-style:none;font-size:.875rem;color:rgba(255,255,255,.75)}
  .assumptions li{margin:6px 0}
  .grid{display:grid;gap:20px;grid-template-columns:1fr 1fr;margin-top:20px}
  .grid.hero{grid-template-columns:1fr;margin-top:0}
  .card{background:#fff;border-radius:20px;padding:28px 24px;box-shadow:0 10px 30px -12px rgba(14,59,46,.15),0 2px 6px -2px rgba(14,59,46,.08);display:flex;flex-direction:column;justify-content:center;min-height:150px}
  .card.hero{padding:36px 32px;min-height:180px}
  .value{font-size:clamp(1.8rem,3vw,3rem);font-weight:700;color:#0E3B2E;line-height:1.1;white-space:nowrap}
  .label{font-size:clamp(.85rem,1vw,1rem);font-weight:500;color:#184D3B;margin-top:6px;white-space:nowrap}
  .title{margin-top:12px;font-size:.72rem;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:#737373}
  .sub-val{margin-top:8px;font-size:.875rem;color:#737373;white-space:nowrap}
  @media (max-width:900px){
    .app{flex-direction:column}
    .left,.right{width:100%}
    .grid{grid-template-columns:1fr}
  }
</style>
</head>
<body>
<div class="app">
  <aside class="left">
    <div class="logo-wrap"><img src="data:image/png;base64," alt="VoltSeal"/></div>
    <h1>Carbon Footprint Calculator</h1>
    <p class="sub">Evaluate the environmental impact of replacing diesel generators with VoltSeal BESS.</p>

    <div class="field">
      <div class="field-head"><label>Power Requirement</label><span class="unit">kW</span></div>
      <input id="power" type="text" inputmode="decimal" placeholder="500" value="500"/>
      <div class="err" id="err-power"></div>
    </div>
    <div class="field">
      <div class="field-head"><label>Daily DG Usage</label><span class="unit">Hours/Day</span></div>
      <input id="hours" type="text" inputmode="decimal" placeholder="2" value="2"/>
      <div class="err" id="err-hours"></div>
    </div>
    <div class="field">
      <div class="field-head"><label>DG Operational Days</label><span class="unit">Days/Year</span></div>
      <input id="days" type="text" inputmode="numeric" placeholder="250" value="250"/>
      <div class="err" id="err-days"></div>
    </div>
    <div class="field">
      <div class="field-head"><label>Carbon Credit Price</label><span class="unit">₹ / Carbon Credit</span></div>
      <input id="price" type="text" inputmode="numeric" placeholder="2000" value="2000"/>
      <div class="err" id="err-price"></div>
    </div>

    <div class="assumptions">
      <h3>Assumptions</h3>
      <ul>
        <li>• Diesel generation efficiency: 3.75 kWh per litre</li>
        <li>• Diesel emission factor: 2.68 kg CO₂ per litre</li>
        <li>• 1 Carbon Credit = 1 tonne CO₂e</li>
        <li>• One mature tree absorbs approximately 22 kg CO₂ annually</li>
      </ul>
    </div>
  </aside>

  <main class="right">
    <div class="grid hero">
      <div class="card hero">
        <div class="value" id="bess-value">—</div>
        <div class="label">Recommended BESS Size</div>
        <div class="sub-val" id="bess-sub"></div>
      </div>
    </div>
    <div class="grid">
      <div class="card"><div class="value" id="energy-value">—</div><div class="label">kWh/year</div><div class="title">Annual Energy Served</div></div>
      <div class="card"><div class="value" id="diesel-value">—</div><div class="label">Litres/year</div><div class="title">Diesel Consumption Avoided</div></div>
    </div>
    <div class="grid">
      <div class="card"><div class="value" id="co2-value">—</div><div class="label">tCO₂e/year</div><div class="title">CO₂ Emissions Avoided</div></div>
      <div class="card"><div class="value" id="credits-value">—</div><div class="label">Credits/year</div><div class="title">Carbon Credits Eligible</div></div>
    </div>
    <div class="grid">
      <div class="card"><div class="value" id="credval-value">—</div><div class="label">Per Year</div><div class="title">Estimated Annual Carbon Credit Value</div></div>
      <div class="card"><div class="value" id="trees-value">—</div><div class="label">Trees</div><div class="title">Equivalent Trees Planted</div></div>
    </div>
  </main>
</div>

<script>
function formatIndian(num, decimals){
  if(!isFinite(num)) return "0";
  decimals = decimals||0;
  var neg = num<0; num = Math.abs(num);
  var fixed = num.toFixed(decimals);
  var parts = fixed.split(".");
  var intPart = parts[0], dec = parts[1];
  var last3 = intPart.slice(-3);
  var other = intPart.slice(0,-3);
  if(other!=="") last3 = ","+last3;
  var out = other.replace(/\B(?=(\d{2})+(?!\d))/g,",")+last3;
  return (neg?"-":"")+out+(dec?"."+dec:"");
}

var state = {power:"500", hours:"2", days:"250", price:"2000"};
var errors = {power:"", hours:"", days:"", price:""};

function setErr(id,msg){ errors[id]=msg; document.getElementById("err-"+id).textContent=msg; }

function onPower(v){
  if(v===""){state.power="";setErr("power","");return recalc();}
  var n=parseFloat(v);
  if(isNaN(n)||n<0){state.power=v;setErr("power","Enter a positive number.");return recalc();}
  state.power=v;setErr("power","");recalc();
}
function onHours(v){
  if(v===""){state.hours="";setErr("hours","");return recalc();}
  var n=parseFloat(v);
  if(isNaN(n)||n<0){state.hours=v;setErr("hours","Enter a value between 0 and 4.");return recalc();}
  if(n>4){state.hours="4";document.getElementById("hours").value="4";setErr("hours","Maximum DG usage per day is 4 hours.");return recalc();}
  state.hours=v;setErr("hours","");recalc();
}
function onDays(v){
  if(v===""){state.days="";setErr("days","");return recalc();}
  if(!/^\d+$/.test(v)){state.days=v;setErr("days","Enter a whole number between 1 and 365.");return recalc();}
  var n=parseInt(v,10);
  if(n<1){state.days=v;setErr("days","Minimum is 1 day.");return recalc();}
  if(n>365){state.days="365";document.getElementById("days").value="365";setErr("days","Maximum DG operational days is 365 days.");return recalc();}
  state.days=v;setErr("days","");recalc();
}
function onPrice(v){
  if(v===""){state.price="";setErr("price","");return recalc();}
  if(!/^\d+$/.test(v)){state.price=v;setErr("price","Enter a whole number between 1 and 1000.");return recalc();}
  var n=parseInt(v,10);
  if(n<1){state.price=v;setErr("price","Minimum is ₹1.");return recalc();}
  if(n>1000){state.price="1000";document.getElementById("price").value="1000";setErr("price","Maximum carbon credit price is ₹1,000 per carbon credit.");return recalc();}
  state.price=v;setErr("price","");recalc();
}

function recalc(){
  var p=parseFloat(state.power)||0;
  var h=parseFloat(state.hours)||0;
  var d=parseInt(state.days,10)||0;
  var pr=parseInt(state.price,10)||0;

  var bess=(p*h)/0.81;
  var annual=bess*d;
  var diesel=annual/3.75;
  var co2kg=diesel*2.68;
  var co2t=co2kg/1000;
  var credits=co2t;
  var credval=credits*pr;
  var trees=Math.floor(co2kg/22);

  var bessDisp, bessSub;
  if(bess>=1000){ bessDisp=(bess/1000).toFixed(2)+" MWh"; }
  else { bessDisp=formatIndian(bess,2)+" kWh"; }
  bessSub="Equivalent to "+formatIndian(bess,0)+" kWh";

  document.getElementById("bess-value").textContent=bessDisp;
  document.getElementById("bess-sub").textContent=bessSub;
  document.getElementById("energy-value").textContent=formatIndian(annual,0);
  document.getElementById("diesel-value").textContent=formatIndian(diesel,0);
  document.getElementById("co2-value").textContent=formatIndian(co2t,2);
  document.getElementById("credits-value").textContent=formatIndian(credits,2);
  document.getElementById("credval-value").textContent="₹"+formatIndian(credval,0);
  document.getElementById("trees-value").textContent=formatIndian(trees,0);
}

document.getElementById("power").addEventListener("input",function(e){onPower(e.target.value)});
document.getElementById("hours").addEventListener("input",function(e){onHours(e.target.value)});
document.getElementById("days").addEventListener("input",function(e){onDays(e.target.value)});
document.getElementById("price").addEventListener("input",function(e){onPrice(e.target.value)});
recalc();
</script>
</body>
</html>
